import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.Cj77QY92.js";const u=JSON.parse('{"title":"RabbitMQ Study Notes: Use Cases, Core Concepts and Reliability","description":"Why message queues matter (decoupling and traffic shaping), how RabbitMQ routes messages, the direct/topic/fanout exchanges, persistence, and the dead letter queue.","frontmatter":{"title":"RabbitMQ Study Notes: Use Cases, Core Concepts and Reliability","date":"2026-09-25T00:00:00.000Z","tags":["RabbitMQ","MQ","Backend"],"readingMinutes":8,"description":"Why message queues matter (decoupling and traffic shaping), how RabbitMQ routes messages, the direct/topic/fanout exchanges, persistence, and the dead letter queue."},"headers":[],"relativePath":"posts/rabbitmq-notes.md","filePath":"posts/rabbitmq-notes.md","lastUpdated":1791828061000}'),n={name:"posts/rabbitmq-notes.md"};function o(r,e,l,h,c,d){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="rabbitmq-study-notes-use-cases-core-concepts-and-reliability" tabindex="-1">RabbitMQ Study Notes: Use Cases, Core Concepts and Reliability <a class="header-anchor" href="#rabbitmq-study-notes-use-cases-core-concepts-and-reliability" aria-label="Permalink to &quot;RabbitMQ Study Notes: Use Cases, Core Concepts and Reliability&quot;">​</a></h1><p class="xq-lead"> Notes from working through RabbitMQ: what a message queue actually buys you, how the pieces fit together, and how to keep messages from getting lost. </p><h2 id="_1-use-cases" tabindex="-1">1. Use cases <a class="header-anchor" href="#_1-use-cases" aria-label="Permalink to &quot;1. Use cases&quot;">​</a></h2><h3 id="_1-1-decoupling" tabindex="-1">1.1 Decoupling <a class="header-anchor" href="#_1-1-decoupling" aria-label="Permalink to &quot;1.1 Decoupling&quot;">​</a></h3><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20261006074211790.png" alt="The purchase flow before the queue" loading="lazy"></p><p>A typical business flow looks like this: purchase → generate a receipt → send an SMS. But generating the receipt and the SMS are not <em>necessary</em> services. If either of them fails, the payment service gets stuck. A message queue solves exactly this problem.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20261006074317128.png" alt="The purchase flow with a message queue" loading="lazy"></p><p>A queue is more like a courier station: the merchant drops the parcel off and is no longer responsible for it — the courier only has to make sure the message reaches the recipient.</p><p>So with a queue the system responds to the user faster, and a failure in the receipt or message module no longer drags down the payment system.</p><h3 id="_1-2-traffic-shaping" tabindex="-1">1.2 Traffic shaping <a class="header-anchor" href="#_1-2-traffic-shaping" aria-label="Permalink to &quot;1.2 Traffic shaping&quot;">​</a></h3><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20261006074336988.png" alt="Requests hitting the system directly" loading="lazy"></p><p>Normally users send requests straight to the system. But if too many users hit the same part at the same moment, the system can crash — and the requests it had not processed yet are lost.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20261006074355971.png" alt="Requests buffered by a queue" loading="lazy"></p><p>With a queue, the queue holds the users&#39; requests. Even if the system crashes, the data in the queue is not lost, and the queue acts as a buffer for the system.</p><h2 id="_2-how-rabbitmq-works" tabindex="-1">2. How RabbitMQ works <a class="header-anchor" href="#_2-how-rabbitmq-works" aria-label="Permalink to &quot;2. How RabbitMQ works&quot;">​</a></h2><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20261006074411819.png" alt="Architecture of RabbitMQ" loading="lazy"></p><ul><li><strong>Broker</strong> — provides the transport service; its role is to maintain the route from producer to consumer and to make sure data is delivered the way it was specified. (The broker is the RabbitMQ server.)</li><li><strong>Exchange</strong> — the message switch: it decides by which rule messages are routed to which queue.</li><li><strong>Queue</strong> — the carrier of messages; every message is delivered to one or more queues.</li><li><strong>Binding</strong> — binds an exchange and a queue together according to routing rules.</li><li><strong>Routing key</strong> — the routing keyword the exchange uses to deliver messages.</li><li><strong>vhost</strong> — virtual host; one broker can hold several vhosts, used to separate the permissions of different users.</li><li><strong>Producer</strong> — the program that publishes messages.</li><li><strong>Consumer</strong> — the program that receives messages.</li><li><strong>Channel</strong> — the message channel; several channels can be created inside each client connection.</li></ul><h2 id="_3-exchanges" tabindex="-1">3. Exchanges <a class="header-anchor" href="#_3-exchanges" aria-label="Permalink to &quot;3. Exchanges&quot;">​</a></h2><p>RabbitMQ has several kinds of exchange.</p><h3 id="direct" tabindex="-1">Direct <a class="header-anchor" href="#direct" aria-label="Permalink to &quot;Direct&quot;">​</a></h3><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20261006074500292.png" alt="Direct exchange" loading="lazy"></p><p>A direct exchange is one-to-one: the client carries a routing key, and the exchange sends the message to the queue bound to that key.</p><h3 id="topic" tabindex="-1">Topic <a class="header-anchor" href="#topic" aria-label="Permalink to &quot;Topic&quot;">​</a></h3><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20261006074515330.png" alt="Topic exchange" loading="lazy"></p><p>Topic works like a topic in MQTT: it matches level by level, and it supports the wildcards <code>#</code> and <code>*</code>.</p><ul><li><code>*</code> matches exactly one word;</li><li><code>#</code> matches zero or more words.</li></ul><p>Suppose the current topic is <code>tree.bee</code>:</p><p>Queue1 and Queue3 receive the message.</p><p>Queue2 does not, because although <code>*</code> can match any word, the client is missing a level — <code>*</code> has to match a word. <code>tree.bee.#</code>, on the other hand, would match.</p><h3 id="fanout" tabindex="-1">Fanout <a class="header-anchor" href="#fanout" aria-label="Permalink to &quot;Fanout&quot;">​</a></h3><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20261006074532152.png" alt="Fanout exchange" loading="lazy"></p><p>Every client receives the message.</p><h2 id="_4-persistence" tabindex="-1">4. Persistence <a class="header-anchor" href="#_4-persistence" aria-label="Permalink to &quot;4. Persistence&quot;">​</a></h2><p>Persistence improves RabbitMQ&#39;s reliability: it prevents data loss in abnormal situations (restart, shutdown, crash). RabbitMQ persistence has three parts: exchange persistence, queue persistence and message persistence.</p><p><strong>Exchange persistence</strong> — turn it on in the configuration:</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20261006074546490.png" alt="Exchange persistence" loading="lazy"></p><p><strong>Queue persistence</strong> — the same as above:</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20261006074600722.png" alt="Queue persistence" loading="lazy"></p><p><strong>Message persistence</strong> — in Spring AMQP, the default value in <code>org.springframework.amqp.core.MessageProperties</code> is 2 (persistent).</p><h2 id="_5-message-acknowledgement" tabindex="-1">5. Message acknowledgement <a class="header-anchor" href="#_5-message-acknowledgement" aria-label="Permalink to &quot;5. Message acknowledgement&quot;">​</a></h2><p>Messages sent to RabbitMQ can be lost, so detecting and handling lost messages is necessary. There are three stages:</p><ul><li>publisher → exchange</li><li>exchange → queue</li><li>queue → client</li></ul><p>Failures in the first two are usually configuration mistakes in the development environment, so they need little handling — an alert to the developer is enough.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20261006074615106.png" alt="The three stages where messages can be lost" loading="lazy"></p><p>A problem in <strong>queue → client</strong>, however, is hard to find in a dev environment, so a separate queue is needed to keep the messages that failed to be delivered. That leads to the <strong>dead letter queue</strong>:</p><ol><li>Create the dead letter queue, exchange and binding (they are ordinary queues and exchanges, just used to store failed messages);</li><li>add the dead letter queue in the listener method that consumes the queue:</li></ol><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/QQ_1791244033693.png" alt="Adding the dead letter queue in the listener" loading="lazy"></p><ol start="3"><li>configure <code>retry</code> in the YAML file:</li></ol><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20261006074628789.png" alt="Retry configuration in YAML" loading="lazy"></p><p>That is how the system decides which messages count as failed.</p>',50)])])}const p=t(n,[["render",o]]);export{u as __pageData,p as default};
